import { Cart, CartItem, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Remove a line item entirely from the cart. (Use Update Cart to reduce quantity of an existing line item.)
*/
export type RemoveFromCart = {
    events: Array<Cart | CartItem | Identity | PartyIdentification | ErrorEvent>;
}

export class RemoveFromCartBuilder {

    private removeFromCart: RemoveFromCart = {
        events: []
    }

    private cart!: Cart;
    private cartItem!: CartItem;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : RemoveFromCartBuilder {
        this.cart = cart;
        return this;
    }
    public withCartItem(cartItem: CartItem) : RemoveFromCartBuilder {
        this.cartItem = cartItem;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : RemoveFromCartBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : RemoveFromCartBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : RemoveFromCartBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : RemoveFromCart {
        if(this.cart) {
            this.removeFromCart.events.push(this.cart);
        }
        if(this.cartItem) {
            this.removeFromCart.events.push(this.cartItem);
        }
        if(this.errorEvent) {
            this.removeFromCart.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.removeFromCart.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.removeFromCart.events.push(this.partyIdentification);
        }

        return this.removeFromCart;
    }
}
